const input = $json;
let context = input.context || {};
if (typeof context === 'string') {
  try { context = JSON.parse(context); } catch (e) { context = {}; }
}
const text = (input.message || '').trim();
const state = input.current_state || 'NEW';

const match = text.toUpperCase().match(/SD-\d{4,}/);

let next_state = state;
let reply = '';
let action = 'NONE';

if (match) {
  context.tracking_number = match[0];
  action = 'LOOKUP';
} else if (state === 'NEW') {
  next_state = 'AWAITING_TRACKING_NUMBER';
  reply = "Sure! What's your tracking number? (e.g. SD-1042)";
} else {
  next_state = 'AWAITING_TRACKING_NUMBER';
  reply = "That doesn't look like a valid tracking number. It should look like SD-1042. Please try again.";
}

return [{
  json: {
    customer_id: input.customer_id,
    phone: input.phone,
    conversation_id: input.conversation_id || null,
    next_state,
    context,
    reply,
    action
  }
}];

const tn = $json.context.tracking_number;
if (tn === 'SD-0000') {
  throw new Error('Tracking service timeout (simulated)');
}
return [{ json: $json }];

const base = $('Process Tracking State').item.json;
return [{
  json: {
    ...base,
    reply: "We're currently unable to retrieve your tracking information. I've sent the request to our operations team for follow-up.",
    next_state: 'HUMAN_ESCALATION',
    found: false
  }
}];

const base = $('Process Tracking State').item.json;
const row = $json;
let reply, next_state;
if (row.status) {
  reply = `Your delivery ${base.context.tracking_number} is currently ${row.status.replace(/_/g, ' ')}.`;
  next_state = 'COMPLETED';
} else {
  reply = `I couldn't find a delivery with tracking number ${base.context.tracking_number}. Please double-check and try again.`;
  next_state = 'AWAITING_TRACKING_NUMBER';
}
return [{ json: { ...base, reply, next_state, found: !!row.status } }];

const f = $('Finalize Payload').item.json;
return [{
  json: {
    reply: f.reply,
    next_state: f.next_state,
    customer_id: f.customer_id,
    conversation_id: f.conversation_id
  }
}];
